import { useEffect, useState } from 'react';
import './SplashScreen.css';

interface SplashScreenProps {
  onComplete: () => void;
}

export function SplashScreen({ onComplete }: SplashScreenProps) {
  const [percentage, setPercentage] = useState(0);

  useEffect(() => {
    // Add specific classes to body temporarily if needed, though we can scope it
    const FILL_DURATION = 2000;
    const START_DELAY = 1500;

    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    if (reduced) {
      setPercentage(100);
      const timer = setTimeout(() => {
        onComplete();
      }, 400);
      return () => clearTimeout(timer);
    } else {
      const startDelayTimer = setTimeout(() => {
        const start = performance.now();
        let animationFrameId: number;

        const tick = (now: number) => {
          const p = Math.min(1, (now - start) / FILL_DURATION);
          setPercentage(Math.floor(p * 100));

          if (p < 1) {
            animationFrameId = requestAnimationFrame(tick);
          } else {
            setTimeout(() => {
              onComplete();
            }, 250);
          }
        };

        animationFrameId = requestAnimationFrame(tick);

        return () => cancelAnimationFrame(animationFrameId);
      }, START_DELAY);

      return () => clearTimeout(startDelayTimer);
    }
  }, [onComplete]);

  return (
    <div className="splash-screen-container">
      <div className="stage">
        <div className="logo-wrap">
          {/* Menggunakan base64 logo dari kode aslinya */}
          <img 
            src="data:image/webp;base64," 
            alt="Logo ORVOKS"
          />
        </div>
        <div className="wordmark">ORVOKS</div>
        <div className="subtitle">Orientasi Vokasi Muda</div>

        <div className="loader">
          <div className="spinner"></div>
          <div className="status-text">Menuju ke Beranda&hellip;</div>
          <div className="progress-track">
            <div className="progress-fill" style={{ width: `${percentage}%` }}></div>
          </div>
          <div className="percentage-text">{percentage}%</div>
        </div>
      </div>
    </div>
  );
}
